function menuFixo(){let e=document.querySelector(".header"),n="fixed";window.addEventListener("scroll",function(){350<window.pageYOffset?e.classList.add(n):e.classList.remove(n)})}menuFixo();
function menuMobile(){let t=document.getElementById("btn-menu"),a=document.getElementById("mobile-menu");var e=a.querySelectorAll("nav ul li");function n(e){"touchstart"===e.type&&e.preventDefault(),t.classList.toggle("active"),a.classList.toggle("open");e=a.classList.contains("open");t.setAttribute("aria-expanded",e),e?t.setAttribute("aria-label","Fechar menu"):t.setAttribute("aria-label","Abrir menu")}function i(){t.classList.remove("active"),a.classList.remove("open"),t.setAttribute("aria-label","Abrir menu"),t.setAttribute("aria-expanded","false")}t.addEventListener("click",n),t.addEventListener("touchstart",n),e.forEach(e=>{e.addEventListener("click",i)})}menuMobile();
let linksInternos=document.querySelectorAll('a[href^="#"]');function scrollToSection(e){e.preventDefault();e=e.currentTarget.getAttribute("href");document.querySelector(e).scrollIntoView({behavior:"smooth",block:"start"})}linksInternos.forEach(e=>{e.addEventListener("click",scrollToSection)});